function Badge({ children, tone = 'neutral' }: { children: ReactNode; tone?: 'neutral' | 'success' | 'warning' | 'danger' | 'info' }) {
  const tones = { neutral: 'bg-slate-100 text-slate-600', success: 'bg-emerald-50 text-emerald-700', warning: 'bg-amber-50 text-amber-700', danger: 'bg-rose-50 text-rose-700', info: 'bg-sky-50 text-sky-700' };
  return <span className={cx('inline-flex items-center gap-1 rounded-sm px-2 py-1 text-[11px] font-semibold', tones[tone])}>{children}</span>;
}
function PageHeader({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description?: string; action?: ReactNode }) {
  return <div className="mb-6 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
    <div><div className="mb-1 text-xs font-semibold tracking-wide text-primary">{eyebrow}</div><h1 className="text-[24px] font-bold tracking-tight text-slate-900">{title}</h1>{description && <p className="mt-1 text-sm text-slate-500">{description}</p>}</div>
    {action && <div className="flex items-center gap-2">{action}</div>}
  </div>;
}
function Button({ children, variant = 'primary', className, onClick, testId, type = 'button' }: { children: ReactNode; variant?: 'primary' | 'secondary' | 'ghost' | 'danger'; className?: string; onClick?: () => void; testId?: string; type?: 'button' | 'submit' }) {
  const variants = { primary: 'bg-primary text-white shadow-sm hover:bg-indigo-700', secondary: 'bg-white text-slate-700 border border-slate-200 hover:border-primary/30 hover:bg-primary/5', ghost: 'text-slate-500 hover:bg-slate-100 hover:text-slate-800', danger: 'bg-rose-50 text-rose-700 hover:bg-rose-100' };
  return <button type={type} onClick={onClick} data-testid={testId} className={cx('inline-flex min-h-9 items-center justify-center gap-2 rounded-md px-3.5 text-sm font-semibold transition-all active:scale-[.98]', variants[variant], className)}>{children}</button>;
}
function IconButton({ children, label, onClick, testId }: { children: ReactNode; label: string; onClick?: () => void; testId?: string }) {
  return <button aria-label={label} title={label} onClick={onClick} data-testid={testId} className="inline-flex h-9 w-9 items-center justify-center rounded-md text-slate-500 transition-colors hover:bg-primary/8 hover:text-primary">{children}</button>;
}
function Modal({ title, children, onClose }: { title: string; children: ReactNode; onClose: () => void }) {
  return <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/35 p-4 backdrop-blur-[2px]" onMouseDown={onClose}><div className="w-full max-w-lg rounded-xl bg-white p-6 shadow-2xl" onMouseDown={(event) => event.stopPropagation()}><div className="mb-5 flex items-center justify-between"><h2 className="text-lg font-bold text-slate-900">{title}</h2><IconButton label="إغلاق" onClick={onClose} testId="button-close-modal"><X size={18} /></IconButton></div>{children}</div></div>;
}
function EmptyState({ icon: Icon, title, description, action }: { icon: typeof Inbox; title: string; description: string; action?: ReactNode }) {
  return <div className="flex min-h-[250px] flex-col items-center justify-center rounded-lg border border-dashed border-slate-200 bg-slate-50/50 p-8 text-center"><div className="mb-3 rounded-xl bg-primary/8 p-3 text-primary"><Icon size={24} /></div><h3 className="font-bold text-slate-800">{title}</h3><p className="mt-1 max-w-sm text-sm text-slate-500">{description}</p>{action && <div className="mt-4">{action}</div>}</div>;
}

