            <Line yAxisId="orders" type="monotone" dataKey="orders" name="الطلبات" stroke="#06b6d4" strokeWidth={2.5} dot={{ r: 3, fill: '#06b6d4', strokeWidth: 2, stroke: '#fff' }} />
