function B2BCoursesPage({ courses }: { courses: Course[] }) {
  return <div className="page-enter"><PageHeader eyebrow="إدارة المحتوى التعليمي" title="دورات الشركات B2B" description="مكتبة الدورات المخصصة لبرامج التدريب المؤسسي." action={<Button testId="button-add-b2b-course"><Plus size={16} />دورة B2B جديدة</Button>} /><div className="grid gap-4 sm:grid-cols-3">{[['الدورات المتاحة', '18', 'bg-indigo-50 text-indigo-700'], ['المقاعد المشغولة', '1,248', 'bg-cyan-50 text-cyan-700'], ['معدل الإكمال', '81.4%', 'bg-emerald-50 text-emerald-700']].map(([label, value, color]) => <div key={label} className="rounded-lg border border-slate-200 bg-white p-4"><div className={cx('mb-3 flex h-8 w-8 items-center justify-center rounded-md', color)}><Building2 size={16} /></div><div className="font-mono text-xl font-bold text-slate-800">{value}</div><div className="mt-1 text-xs text-slate-400">{label}</div></div>)}</div><div className="mt-6 grid gap-5 lg:grid-cols-2">{courses.map((course) => <Link key={course.id} href={`/b2blibrary/courses/${course.id}`} data-testid={`card-b2b-course-${course.id}`} className="card-lift rounded-lg border border-slate-200 bg-white p-5"><div className="flex items-start gap-4"><div className="flex h-14 w-16 items-end rounded-md bg-gradient-to-br from-indigo-800 to-cyan-500 p-2 font-mono text-[10px] font-bold text-white">{course.id}</div><div className="min-w-0 flex-1"><div className="flex items-center justify-between gap-2"><Badge tone="info">B2B</Badge><span className="font-mono text-xs text-slate-400">{course.stats.enrolledStudents} مقعداً</span></div><h2 className="mt-3 font-bold leading-7 text-slate-800">{course.title}</h2><p className="mt-1 text-xs text-slate-400">{course.category}</p></div></div><div className="mt-5 flex items-center justify-between border-t border-slate-100 pt-4 text-xs text-slate-500"><span>معدل الإكمال {course.stats.completionRate}%</span><span className="font-semibold text-primary">فتح التفاصيل <ArrowLeft className="mr-1 inline" size={13} /></span></div></Link>)}</div></div>;
}

function B2BCourseDetailPage({ courses }: { courses: Course[] }) {
  const { id } = useParams<{ id: string }>();
  const course = courses.find((item) => item.id === id) ?? courses[0];
  const tabs = ['وصف الدورة', 'الأقسام التدريبية', 'البث المباشر', 'الاختبارات والواجبات', 'التقارير'];
  const [tab, setTab] = useState(tabs[0]);
  return <div className="page-enter"><div className="mb-5 flex items-center gap-2 text-xs text-slate-400"><Link href="/b2blibrary/courses" className="hover:text-primary">دورات الشركات B2B</Link><ChevronLeft size={13} /><span>{course.id}</span></div><section className="overflow-hidden rounded-lg border border-slate-200 bg-white"><div className="bg-gradient-to-l from-indigo-950 to-slate-800 p-6 text-white"><Badge tone="info">دورة مؤسسية B2B</Badge><h1 className="mt-4 max-w-3xl text-2xl font-bold leading-loose">{course.title}</h1><div className="mt-4 flex flex-wrap gap-6 text-xs text-indigo-100"><span><b className="block font-mono text-lg text-white">{course.stats.enrolledStudents}</b>مقعد مشغول</span><span><b className="block font-mono text-lg text-white">{course.stats.completionRate}%</b>معدل الإكمال</span><span><b className="block font-mono text-lg text-white">{course.trainers[0]?.name}</b>المدرب المسؤول</span></div></div><div className="scrollbar-thin flex overflow-x-auto border-b border-slate-100 px-3">{tabs.map((item) => <button key={item} onClick={() => setTab(item)} className={cx('relative shrink-0 px-4 py-4 text-sm font-semibold', tab === item ? 'text-primary' : 'text-slate-500')}><span>{item}</span>{tab === item && <span className="absolute inset-x-4 bottom-0 h-0.5 bg-primary" />}</button>)}</div><div className="p-5 sm:p-7">{tab === 'وصف الدورة' && <div className="grid gap-6 lg:grid-cols-[1.3fr_.7fr]"><div><h2 className="font-bold text-slate-800">وصف البرنامج المؤسسي</h2><p className="mt-3 text-sm leading-8 text-slate-600">مسار تدريبي قابل للتخصيص للفرق والشركات، مع تقارير تقدم ومواعيد بث مباشر ومحتوى عملي قابل للقياس.</p><Button className="mt-5"><Pencil size={15} />تعديل الوصف</Button></div><div className="rounded-lg bg-slate-50 p-4"><div className="text-xs text-slate-400">حالة النشر</div><div className="mt-2"><Badge tone="success">متاح للشركات</Badge></div><div className="mt-4 text-xs text-slate-400">سعر المقعد</div><div className="mt-1 font-mono text-lg font-bold">{money(course.price)}</div></div></div>}{tab === 'الأقسام التدريبية' && <Curriculum course={course} openSections={course.curriculumSections.map((section) => section.id)} setOpenSections={() => undefined} />}{tab === 'البث المباشر' && <FlowListPage eyebrow="إدارة الدورة" title="جلسات البث المباشر" description="جدولة جلسات مخصصة لمجموعات الشركات." icon={Video} rows={[{ id: 'LIVE-01', title: 'جلسة تطبيقية للفرق', subtitle: 'الثلاثاء 15 سبتمبر · 6:00 مساءً', metric: '45 مقعداً', status: 'مجدولة', detail: 'رابط الاجتماع جاهز', tone: 'success' }]} actionLabel="جلسة جديدة" />}{tab === 'الاختبارات والواجبات' && <Assessments />}{tab === 'التقارير' && <ReportPage />}</div></section></div>;
}

function PackageDetailPage() {
  const [tab, setTab] = useState('overview');
  const tabs = [['overview', 'الوصف وإدارة الدورات'], ['users', 'المتدربون'], ['sales', 'مبيعات الباقة'], ['settings', 'الأسعار والشروط']];
  return <div className="page-enter"><div className="mb-5 flex items-center gap-2 text-xs text-slate-400"><Link href="/curricula" className="hover:text-primary">الباقات التدريبية</Link><ChevronLeft size={13} /><span>PKG-01</span></div><section className="overflow-hidden rounded-lg border border-slate-200 bg-white"><div className="bg-gradient-to-l from-indigo-950 to-indigo-700 p-6 text-white"><Badge tone="success">نشطة</Badge><h1 className="mt-4 text-2xl font-bold">باقة التسويق والتجارة الإلكترونية الشاملة</h1><div className="mt-4 flex gap-6 text-xs text-indigo-100"><span><b className="block font-mono text-lg text-white">119</b>مشتركاً</span><span><b className="block font-mono text-lg text-white">1,499 ر.س</b>السعر الحالي</span><span><b className="block font-mono text-lg text-white">3</b>دورات مرتبطة</span></div></div><div className="scrollbar-thin flex overflow-x-auto border-b border-slate-100 px-3">{tabs.map(([key, label]) => <button key={key} onClick={() => setTab(key)} className={cx('relative shrink-0 px-4 py-4 text-sm font-semibold', tab === key ? 'text-primary' : 'text-slate-500')}>{label}{tab === key && <span className="absolute inset-x-4 bottom-0 h-0.5 bg-primary" />}</button>)}</div><div className="p-5 sm:p-7">{tab === 'overview' && <div className="grid gap-6 lg:grid-cols-2"><section><h2 className="font-bold">وصف الباقة</h2><p className="mt-3 text-sm leading-8 text-slate-600">مسار متكامل يجمع دورات التسويق الرقمي والتجارة الإلكترونية وتحليل البيانات في تجربة واحدة.</p><Button className="mt-5"><Pencil size={15} />تعديل الوصف</Button></section><section><h2 className="font-bold">الدورات المرتبطة</h2><div className="mt-3 space-y-2">{['تحليل البيانات واستخراج الأنماط', 'التسويق الرقمي العملي', 'أساسيات التجارة الإلكترونية'].map((item, index) => <div key={item} className="flex items-center gap-3 rounded-md border border-slate-200 p-3 text-sm"><span className="font-mono text-xs text-slate-400">0{index + 1}</span><span className="font-semibold">{item}</span><CheckCircle2 size={15} className="mr-auto text-emerald-500" /></div>)}</div></section></div>}{tab === 'users' && <FlowListPage eyebrow="تفاصيل الباقة" title="المتدربون في الباقة" description="بحث وتصفية المتدربين المشتركين في هذه الباقة." icon={Users} rows={[{ id: 'USR-1001', title: 'ريم الدوسري', subtitle: '3 دورات · آخر نشاط اليوم', metric: '82%', status: 'مستمر', tone: 'info' }, { id: 'USR-1002', title: 'خالد المطيري', subtitle: 'دورتان · آخر نشاط أمس', metric: '61%', status: 'مستمر', tone: 'info' }]} actionLabel="إضافة متدرب" />}{tab === 'sales' && <ReportPage />}{tab === 'settings' && <div className="grid gap-4 sm:grid-cols-2"><Field label="سعر الباقة" name="bundle-price" value="1499 ر.س" onChange={() => undefined} /><Field label="مدة الصلاحية" name="bundle-validity" value="180 يوماً" onChange={() => undefined} /><Field label="شروط الإتمام" name="bundle-completion" value="إكمال 80% من الدروس" onChange={() => undefined} /><Button>حفظ إعدادات الباقة</Button></div>}</div></section></div>;
}

function ConsultantDetailPage() {
  const { id } = useParams<{ id: string }>();
  const consultant = id === '2' ? { name: 'م. فهد السبيعي', role: 'التحول الرقمي للمنشآت', price: 480 } : { name: 'د. ليان العبدالله', role: 'استراتيجية الأعمال والحوكمة', price: 650 };
  return <div className="page-enter"><div className="mb-5 flex items-center gap-2 text-xs text-slate-400"><Link href="/consultancy/consultants" className="hover:text-primary">المستشارون</Link><ChevronLeft size={13} /><span>{consultant.name}</span></div><PageHeader eyebrow="إدارة الاستشارات" title={consultant.name} description={consultant.role} action={<Button><Pencil size={15} />تعديل الملف</Button>} /><div className="grid gap-4 sm:grid-cols-4">{[['إجمالي المبلغ', money(consultant.price * 18), 'bg-indigo-50 text-indigo-700'], ['عدد الاستشارات', '18', 'bg-cyan-50 text-cyan-700'], ['الجلسات المنفذة', '16', 'bg-emerald-50 text-emerald-700'], ['إجمالي الوقت', '24 ساعة', 'bg-amber-50 text-amber-700']].map(([label, value, color]) => <div key={label} className="rounded-lg border border-slate-200 bg-white p-4"><div className={cx('mb-3 flex h-8 w-8 items-center justify-center rounded-md', color)}><BarChart3 size={16} /></div><div className="font-mono text-xl font-bold text-slate-800">{value}</div><div className="mt-1 text-xs text-slate-400">{label}</div></div>)}</div><div className="mt-6 grid gap-6 lg:grid-cols-[1.1fr_.9fr]"><section className="rounded-lg border border-slate-200 bg-white p-5"><div className="flex items-center justify-between"><div><h2 className="font-bold">جميع الاستشارات</h2><p className="mt-1 text-xs text-slate-400">آخر الحجوزات والجلسات المنفذة.</p></div><Button variant="secondary"><Download size={14} />تصدير</Button></div><div className="mt-4 space-y-2">{['شركة مدار الصحية', 'نورة عبدالعزيز', 'مجموعة السالم'].map((client, index) => <div key={client} className="flex items-center gap-3 rounded-md border border-slate-100 p-3"><div className="flex h-8 w-8 items-center justify-center rounded-full bg-indigo-50 text-xs font-bold text-indigo-700">{initials(client)}</div><div className="flex-1"><div className="text-sm font-semibold">{client}</div><div className="mt-1 text-xs text-slate-400">{index === 0 ? 'منفذة · 90 دقيقة' : 'محجوزة · سبتمبر ٢٠٢٦'}</div></div><Badge tone={index === 0 ? 'success' : 'info'}>{index === 0 ? 'مكتملة' : 'مجدولة'}</Badge></div>)}</div></section><section className="rounded-lg border border-slate-200 bg-white p-5"><h2 className="font-bold">إعدادات التوفر</h2><div className="mt-4 space-y-3">{['الأحد والثلاثاء', 'من 4:00 م إلى 8:00 م', 'الحجز قبل الموعد بـ 24 ساعة'].map((item) => <div key={item} className="flex items-center gap-2 rounded-md bg-slate-50 p-3 text-sm text-slate-600"><CheckCircle2 size={15} className="text-emerald-500" />{item}</div>)}</div><Button className="mt-5 w-full">تعديل الجدول</Button></section></div></div>;
}

function CourseFeaturePage({ courses }: { courses: Course[] }) {
  const { id, section } = useParams<{ id: string; section: string }>();
  const course = courses.find((item) => item.id === id) ?? courses[0];
  const featureMeta: Record<string, { title: string; description: string; icon: typeof FolderKanban; action: string; rows: FlowRow[] }> = {
    description: { title: 'وصف الدورة', description: 'اكتب الوصف التسويقي والأهداف التعليمية للدورة.', icon: FileText, action: 'حفظ الوصف', rows: [{ id: 'DESC-01', title: course.title, subtitle: 'وصف تسويقي محدث · الأهداف والمخرجات التعليمية', metric: 'جاهز', status: 'منشور', tone: 'success' }] },
    sections: { title: 'الأقسام التدريبية', description: 'أدر الوحدات والدروس ورتب رحلة التعلم.', icon: BookOpen, action: 'قسم جديد', rows: course.curriculumSections.map((item) => ({ id: item.id, title: item.title, subtitle: `${item.items.length} عناصر تعليمية`, metric: `${item.order}`, status: 'متاح', tone: 'success' as const })) },
    live: { title: 'البث المباشر', description: 'جدول الجلسات المباشرة وروابط الحضور.', icon: Video, action: 'جلسة مباشرة', rows: [{ id: 'LIVE-01', title: 'تطبيقات بايثون في التنقيب عن البيانات', subtitle: 'الثلاثاء 15 سبتمبر · 6:00 مساءً', metric: '90 دقيقة', status: 'مجدولة', tone: 'info' }] },
    activities: { title: 'الأنشطة التدريبية', description: 'أنشئ أنشطة تفاعلية تساعد على تثبيت المعرفة.', icon: Sparkles, action: 'نشاط جديد', rows: [{ id: 'ACT-01', title: 'ربط الخوارزميات بالاستخدام المناسب', subtitle: 'نشاط مطابقة · الوحدة الثانية', metric: '12 سؤالاً', status: 'نشط', tone: 'success' }] },
    exams: { title: 'الاختبارات', description: 'إدارة الاختبارات ودرجات الاجتياز والمحاولات.', icon: ClipboardList, action: 'اختبار جديد', rows: [{ id: 'EXM-01', title: 'الاختبار النهائي للدورة', subtitle: '30 سؤالاً · 3 محاولات', metric: '75%', status: 'منشور', tone: 'success' }] },
    assignments: { title: 'الواجبات', description: 'راجع الواجبات ومواعيد التسليم والتقييم.', icon: FileText, action: 'واجب جديد', rows: [{ id: 'ASM-01', title: 'تنظيف مجموعة بيانات المبيعات', subtitle: 'تسليم خلال 5 أيام', metric: '42 تسليماً', status: 'مفتوح', tone: 'info' }] },
    rating: { title: 'تقييم الدورة', description: 'تابع آراء المتدربين ومتوسط التقييم.', icon: BarChart3, action: 'تصدير التقييمات', rows: [{ id: 'RAT-01', title: 'متوسط التقييم العام', subtitle: '112 تقييماً من المتدربين', metric: '4.9 / 5', status: 'ممتاز', tone: 'success' }] },
    images: { title: 'صور الدورة', description: 'أدر صورة الغلاف والصور المستخدمة داخل المحتوى.', icon: Eye, action: 'إضافة صورة', rows: [{ id: 'IMG-01', title: 'غلاف الدورة الرئيسي', subtitle: 'الصورة المستخدمة في المكتبة', metric: '1200×800', status: 'أساسية', tone: 'success' }] },
    instructors: { title: 'المدربون', description: 'أدر المدربين المشاركين وأدوارهم في الدورة.', icon: GraduationCap, action: 'إضافة مدرب', rows: course.trainers.map((trainer) => ({ id: trainer.id, title: trainer.name, subtitle: 'مدرب مشارك في الدورة', metric: 'مفعل', status: 'نشط', tone: 'success' as const })) },
    certificates: { title: 'الشهادات', description: 'صمم الشهادة وحدد قواعد إصدارها.', icon: ShieldCheck, action: 'إعداد الشهادة', rows: [{ id: 'CERT-01', title: 'شهادة إتمام الدورة', subtitle: 'تُصدر تلقائياً عند تحقيق شروط الإكمال', metric: '75%', status: 'مفعلة', tone: 'success' }] },
    completion: { title: 'شروط إكمال الدورة', description: 'حدد المتطلبات التي تؤهل المتدرب للحصول على الشهادة.', icon: CheckCircle2, action: 'شرط جديد', rows: [{ id: 'CMP-01', title: 'إكمال المحتوى الأساسي', subtitle: 'مشاهدة جميع الدروس والمواد', metric: '100%', status: 'مفعل', tone: 'success' }, { id: 'CMP-02', title: 'اجتياز الاختبار النهائي', subtitle: 'الحد الأدنى للنجاح', metric: '75%', status: 'مفعل', tone: 'success' }] },
    prices: { title: 'قائمة الأسعار', description: 'أدر السعر الأساسي وأسعار المؤسسات والعروض.', icon: WalletCards, action: 'سعر جديد', rows: [{ id: 'PRC-01', title: 'السعر الأساسي', subtitle: 'السعر الظاهر للمتعلم الفردي', metric: money(course.price), status: 'نشط', tone: 'success' }, { id: 'PRC-02', title: 'سعر الشركات', subtitle: 'يطبق على طلبات B2B', metric: money(course.price * 0.8), status: 'نشط', tone: 'info' }] },
    announcements: { title: 'الإعلانات', description: 'أرسل تحديثات وإعلانات للمتدربين المسجلين.', icon: Bell, action: 'إعلان جديد', rows: [{ id: 'ANN-01', title: 'تذكير بالجلسة المباشرة', subtitle: 'تم إرساله إلى جميع المتدربين', metric: '420 مستلماً', status: 'مرسل', tone: 'success' }] },
    cases: { title: 'الحالات الدراسية', description: 'أضف حالات تطبيقية مرتبطة بأهداف الدورة.', icon: FolderKanban, action: 'حالة جديدة', rows: [{ id: 'CASE-01', title: 'تحليل بيانات متجر إلكتروني', subtitle: 'حالة تطبيقية · الوحدة الثالثة', metric: 'PDF', status: 'متاح', tone: 'success' }] },
    attendance: { title: 'سجل الحضور الشخصي', description: 'راجع حضور المتدربين في الأنشطة والجلسات.', icon: CalendarDays, action: 'تسجيل حضور', rows: [{ id: 'ATT-01', title: 'جلسة البث المباشر الأولى', subtitle: '15 سبتمبر ٢٠٢٦ · 45 حاضراً', metric: '89%', status: 'مكتمل', tone: 'success' }] },
    glossary: { title: 'قائمة المصطلحات', description: 'أنشئ قاموساً يساعد المتدربين على فهم المصطلحات.', icon: FileText, action: 'مصطلح جديد', rows: [{ id: 'GLS-01', title: 'التنقيب عن البيانات', subtitle: 'استخراج الأنماط من مجموعات البيانات', metric: 'AR / EN', status: 'منشور', tone: 'success' }] },
    discussions: { title: 'النقاشات', description: 'أدر مساحات النقاش والإشراف على تفاعل المتدربين.', icon: Users, action: 'موضوع جديد', rows: [{ id: 'DSC-01', title: 'أفضل أدوات التحليل', subtitle: '32 مشاركة · آخر مشاركة اليوم', metric: '32', status: 'نشط', tone: 'info' }] },
    wiki: { title: 'الموسوعة الحرة', description: 'اجمع المراجع والمصادر التي يمكن للمتدرب الرجوع إليها.', icon: BookOpen, action: 'مرجع جديد', rows: [{ id: 'WKI-01', title: 'مرجع مكتبة Pandas', subtitle: 'رابط خارجي · مراجع إضافية', metric: 'رابط', status: 'متاح', tone: 'success' }] },
    reports: { title: 'تقارير الدورة', description: 'حلل التقدم والإكمال والإيرادات الخاصة بالدورة.', icon: BarChart3, action: 'تصدير التقرير', rows: [{ id: 'RPT-01', title: 'تقرير أداء الدورة', subtitle: 'الفترة الحالية · سبتمبر ٢٠٢٦', metric: money(course.stats.totalRevenue), status: 'محدث', tone: 'success' }] },
  };
  const meta = featureMeta[section] ?? featureMeta.description;
  return <div className="page-enter"><div className="mb-5 flex items-center gap-2 text-xs text-slate-400"><Link href={`/courses/${course.id}`} className="hover:text-primary">تفاصيل الدورة</Link><ChevronLeft size={13} /><span>{meta.title}</span></div><PageHeader eyebrow={`إدارة الدورة · ${course.id}`} title={meta.title} description={meta.description} action={<Button><Plus size={15} />{meta.action}</Button>} /><section className="rounded-lg border border-slate-200 bg-white p-5 sm:p-7"><div className="mb-5 flex items-center gap-3 rounded-lg bg-indigo-50/70 p-4"><div className="flex h-10 w-10 items-center justify-center rounded-md bg-white text-primary"><BookOpen size={18} /></div><div><div className="text-sm font-bold text-indigo-950">{course.title}</div><div className="mt-1 text-xs text-indigo-700">{course.category} · {course.stats.enrolledStudents} متدرباً</div></div></div><FlowListPage eyebrow="محتوى الدورة" title={meta.title} description={meta.description} icon={meta.icon} rows={meta.rows} actionLabel={meta.action} /></section></div>;
}

function PlaceholderPage({ title }: { title: string }) { return <div className="page-enter"><PageHeader eyebrow="مساحة العمل" title={title} description="هذه الوحدة قيد التهيئة ضمن مركز عمليات مَدار." /><EmptyState icon={FolderKanban} title="قريباً في مساحة العمل" description="تم تجهيز مسار التنقل، وستتوفر أدوات هذه الوحدة في الإصدار القادم." action={<Link href="/dashboard" data-testid="link-placeholder-dashboard" className="inline-flex min-h-9 items-center gap-2 rounded-md bg-primary px-4 text-sm font-semibold text-white">العودة إلى لوحة التحكم <ArrowLeft size={15} /></Link>} /></div>; }

function AppRoutes({ courses, setCourses, coupons, setCoupons, tickets, setTickets, onQuickAdd }: { courses: Course[]; setCourses: (value: Course[]) => void; coupons: Coupon[]; setCoupons: (value: Coupon[]) => void; tickets: TicketType[]; setTickets: (value: TicketType[]) => void; onQuickAdd: (type: 'course' | 'coupon' | 'b2b') => void }) {
  return <Shell><Switch>
    <Route path="/" component={() => <DashboardPage onQuickAdd={onQuickAdd} />} />
    <Route path="/home" component={() => <DashboardPage onQuickAdd={onQuickAdd} />} />
    <Route path="/dashboard" component={() => <DashboardPage onQuickAdd={onQuickAdd} />} />

    <Route path="/courses/courses" component={() => <CoursesPage courses={courses} onChange={setCourses} />} />
    <Route path="/courses" component={() => <CoursesPage courses={courses} onChange={setCourses} />} />
    <Route path="/courses/:id/manage/:section" component={() => <CourseFeaturePage courses={courses} />} />
    <Route path="/courses/:id" component={() => <CourseWorkspace courses={courses} onChange={setCourses} />} />

    <Route path="/b2blibrary/courses" component={() => <B2BCoursesPage courses={courses} />} />
    <Route path="/b2blibrary/courses/:id" component={() => <B2BCourseDetailPage courses={courses} />} />

    <Route path="/curricula/:id" component={PackageDetailPage} />
    <Route path="/curricula" component={PackagesPage} />
    <Route path="/packages/:id" component={PackageDetailPage} />
    <Route path="/packages" component={PackagesPage} />

    <Route path="/consultancy/consultants/:id" component={ConsultantDetailPage} />
    <Route path="/consultancy/consultants" component={ConsultationsPage} />
    <Route path="/consultations" component={ConsultationsPage} />

    <Route path="/coupons" component={() => <CouponsPage coupons={coupons} onChange={setCoupons} />} />
    <Route path="/affiliates/managers" component={() => <FlowListPage eyebrow="نظام التسويق" title="إدارة المسوقين" description="إدارة حسابات المسوقين وأكواد الإحالة ومعدلات التحويل." icon={Users} actionLabel="مسوق جديد" rows={[{ id: 'AFF-201', title: 'زايد أحمد أبو زايد', subtitle: 'ZAID2026 · تحويل بنكي', metric: '84', status: 'نشط', detail: money(9450), tone: 'success' }, { id: 'AFF-202', title: 'محسنة حسين أحمد الفيفي', subtitle: 'HAYAS10 · STC Pay', metric: '19', status: 'نشط', detail: money(1710), tone: 'success' }]} detailPrefix="/affiliates/managers" />} />
    <Route path="/affiliates/commissions" component={() => <FlowListPage eyebrow="نظام التسويق" title="إدارة العمولات" description="راجع العمولات حسب المسوق والطلب وحالة الاستحقاق." icon={Percent} actionLabel="تسوية عمولة" rows={[{ id: 'COM-01', title: 'عمولة طلب ORD-9211', subtitle: 'زايد أحمد أبو زايد · 10%', metric: money(85), status: 'مستحقة', detail: 'تستحق ١٥ سبتمبر', tone: 'warning' }, { id: 'COM-02', title: 'عمولة طلب ORD-9208', subtitle: 'محسنة حسين أحمد الفيفي · 8%', metric: money(120), status: 'معتمدة', detail: 'تم الدفع', tone: 'success' }]} />} />
    <Route path="/affiliates/payments" component={() => <FlowListPage eyebrow="نظام التسويق" title="طلبات الدفع" description="اعتمد طلبات سحب العمولات وتابع حالة التحويل." icon={WalletCards} actionLabel="مراجعة الدفعات" rows={[{ id: 'PAY-01', title: 'زايد أحمد أبو زايد', subtitle: 'تحويل بنكي · ZAID2026', metric: money(2100), status: 'بانتظار الاعتماد', detail: 'اليوم', tone: 'warning' }, { id: 'PAY-02', title: 'محسنة حسين أحمد الفيفي', subtitle: 'STC Pay · HAYAS10', metric: money(510), status: 'مكتملة', detail: '٣١ أغسطس', tone: 'success' }]} />} />
    <Route path="/affiliates/policy" component={() => <PolicyPage kind="affiliate" />} />
    <Route path="/affiliates" component={AffiliatesPage} />
    <Route path="/new-affliate" component={MarketingPage} />

    <Route path="/b2b/new" component={() => <FlowListPage eyebrow="بوابة الشركات B2B" title="الطلبات الجديدة" description="طلبات الشركات التي تحتاج إلى تواصل أولي." icon={Building2} actionLabel="طلب شركة جديد" rows={b2bSeed.filter((row) => row.stage === 'new_request').map((row) => ({ id: row.id, title: row.companyName, subtitle: row.contactPerson, metric: `${row.requestedSeats} مقعداً`, status: 'جديد', detail: row.createdAt, tone: 'info' as const }))} />} />
    <Route path="/b2b/contacted" component={() => <FlowListPage eyebrow="بوابة الشركات B2B" title="تم التواصل معهم" description="تابع الشركات التي بدأت معها محادثة تجارية." icon={Building2} actionLabel="تحديث الطلب" rows={b2bSeed.filter((row) => row.stage === 'contacted').map((row) => ({ id: row.id, title: row.companyName, subtitle: row.contactPerson, metric: `${row.requestedSeats} مقعداً`, status: 'تم التواصل', detail: row.createdAt, tone: 'warning' as const }))} />} />
    <Route path="/b2b/active" component={() => <FlowListPage eyebrow="بوابة الشركات B2B" title="إدارة الاشتراكات المفعلة" description="أدر الاشتراكات المؤسسية النشطة ومقاعدها." icon={Building2} actionLabel="اشتراك جديد" rows={b2bSeed.filter((row) => row.stage === 'active_subscription').map((row) => ({ id: row.id, title: row.companyName, subtitle: row.assignedPackage, metric: `${row.requestedSeats} مقعداً`, status: 'نشط', detail: row.createdAt, tone: 'success' as const }))} />} />
    <Route path="/b2b/consultations" component={() => <FlowListPage eyebrow="بوابة الشركات B2B" title="طلبات الاستشارات" description="نسّق طلبات جلسات الاستشارة الخاصة بالشركات." icon={CalendarDays} actionLabel="تسجيل طلب" rows={b2bSeed.filter((row) => row.stage === 'consultation_request').map((row) => ({ id: row.id, title: row.companyName, subtitle: row.contactPerson, metric: `${row.requestedSeats} مقعداً`, status: 'استشارة', detail: row.createdAt, tone: 'info' as const }))} />} />
    <Route path="/b2b/policy" component={() => <PolicyPage kind="b2b" />} />
    <Route path="/b2b" component={B2BPage} />

    <Route path="/sales" component={SalesPage} />
    <Route path="/reports/:kind" component={ReportPage} />
    <Route path="/reports" component={() => <ReportPage />} />

    <Route path="/users/names" component={() => <ManagementPage section="names" />} />
    <Route path="/users/trainer-requests" component={() => <ManagementPage section="trainerRequests" />} />
    <Route path="/users/admins" component={() => <ManagementPage section="admins" />} />
    <Route path="/users/trainers" component={() => <ManagementPage section="trainers" />} />
    <Route path="/users" component={() => <ManagementPage section="query" />} />
    <Route path="/reviews" component={ReviewsPage} />

    <Route path="/tickets" component={() => <TicketsPage tickets={tickets} setTickets={setTickets} />} />
    <Route path="/system/tickets" component={() => <TicketsPage tickets={tickets} setTickets={setTickets} />} />
    <Route path="/policies" component={() => <PolicyPage />} />
    <Route path="/settings" component={SettingsPage} />
    <Route component={() => <PlaceholderPage title="الصفحة غير موجودة" />} />
  </Switch></Shell>;
}

function App() {
  const [courses, setCourses] = useState(coursesSeed); const [coupons, setCoupons] = useState(couponsSeed); const [tickets, setTickets] = useState(ticketsSeed); const [quick, setQuick] = useState<'course' | 'coupon' | 'b2b' | null>(null);
  const quickContent = useMemo(() => quick === 'course' ? { title: 'إضافة دورة سريعة', text: 'انتقل إلى إدارة الدورات لإضافة دورة جديدة إلى المكتبة.' } : quick === 'coupon' ? { title: 'إنشاء كوبون سريع', text: 'أنت على بعد خطوة من إطلاق عرض جديد.' } : { title: 'إضافة عميل شركات', text: 'سجّل طلب شركة جديداً وابدأ رحلة التحويل.' }, [quick]);
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><ErrorBoundary resetKey={useLocation()[0]}><AppRoutes courses={courses} setCourses={setCourses} coupons={coupons} setCoupons={setCoupons} tickets={tickets} setTickets={setTickets} onQuickAdd={setQuick} /></ErrorBoundary></WouterRouter><Toaster />{quick && <Modal title={quickContent.title} onClose={() => setQuick(null)}><div className="rounded-md bg-indigo-50 p-4 text-sm leading-7 text-indigo-800">{quickContent.text}</div><div className="mt-5 flex justify-end"><Button onClick={() => setQuick(null)} testId="button-close-quick-action">حسناً</Button></div></Modal>}</TooltipProvider></QueryClientProvider>;
}

export default App;